/// Computes element-wise `a % b` for two equally-long vectors of non-zero divisors.
#[verifier(external_body)]
#[requires(arr1.len() == arr2.len())]
#[requires(forall(|i: usize| i < arr2.len() ==> arr2[i] != 0))]
#[ensures(result.len() == arr1.len())]
#[ensures(forall(|i: usize| i < arr1.len() ==>
    result[i] == arr1[i] % arr2[i]
))]
fn element_wise_module(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    // They are guaranteed to have the same length, but we can assert in debug builds.
    debug_assert_eq!(arr1.len(), arr2.len());

    arr1.iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| a % b)
        .collect()
}

